parameters.jsCode:
const SIZES = ['1-10', '11-50', '51-200', '201-1000', '1000+', 'unknown'];
const INTENTS = ['high', 'medium', 'low'];
const FALLBACK_MAX = 69; // below the hot-lead threshold: no alert without a real AI score

const lead = $('Load Lead').item.json;
const res = $json;
const problems = [];
let out = null;

const content = res?.choices?.[0]?.message?.content;
if (res?.error) problems.push('LLM request failed: ' + (res.error.message ?? JSON.stringify(res.error)).slice(0, 200));
else if (typeof content !== 'string') problems.push('LLM returned no content');
else {
  try { out = JSON.parse(content.replace(/^\s*```(?:json)?\s*|\s*```\s*$/g, '')); }
  catch { problems.push('LLM output is not valid JSON'); }
}

if (out) {
  if (!Number.isInteger(out.score) || out.score < 0 || out.score > 100) problems.push('score not an integer 0-100');
  if (!INTENTS.includes(out.intent)) problems.push('intent not one of ' + INTENTS.join('/'));
  if (!SIZES.includes(out.company_size)) problems.push('company_size not allowed');
  if (typeof out.industry !== 'string' || !out.industry.trim()) problems.push('industry missing');
  if (typeof out.reason !== 'string' || !out.reason.trim()) problems.push('reason missing');
}

if (problems.length === 0) {
  return { json: {
    leadId: lead.id, score: out.score, industry: out.industry.trim().slice(0, 100),
    company_size: out.company_size, intent: out.intent, reason: out.reason.trim().slice(0, 600),
    model: res.model ?? $env.LLM_MODEL, fallback: false,
  } };
}

// Rule-based fallback, so a lead is never left unscored.
const budget = Number(lead.raw_payload?.estimatedBudget ?? 0);
const why = [];
let score = 30;
if (budget >= 50000) { score += 30; why.push('budget >= 50k'); }
else if (budget >= 10000) { score += 15; why.push('budget >= 10k'); }
if (lead.crm_company_id) { score += 10; why.push('company identified'); }
if ((lead.message ?? '').length > 80) { score += 10; why.push('detailed message'); }

return { json: {
  leadId: lead.id, score: Math.min(score, FALLBACK_MAX), industry: 'unknown', company_size: 'unknown',
  intent: budget >= 10000 ? 'medium' : 'low',
  reason: 'Rule-based fallback (' + (why.join(', ') || 'no signals') + '). AI output rejected: ' + problems.join('; '),
  model: res?.model ?? null, fallback: true,
} };

