INSERT INTO event_log (workflow_name, event_type, entity_type, entity_id, message, data, execution_id)
VALUES ($1, $2, $3, $4, $5, $6::jsonb, $7)
RETURNING id AS event_id;

parameters.jsCode:
const s = $('Parse & Validate Score').item.json;
const l = $('Load Lead').item.json;
const esc = (v) => String(v ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const name = [l.first_name, l.last_name].filter(Boolean).join(' ');
const crmLink = l.crm_opportunity_id
  ? $env.TWENTY_PUBLIC_URL + '/object/opportunity/' + l.crm_opportunity_id
  : null;

const rows = [
  ['Score', s.score + ' / 100 (' + s.intent + ' intent)'],
  ['Company', l.company || '-'],
  ['Contact', name + ' &lt;' + esc(l.email) + '&gt;'],
  ['Country / language', (l.country || '-') + ' / ' + l.language],
  ['Industry / size', s.industry + ' / ' + s.company_size + ' employees'],
  ['Budget', l.raw_payload?.estimatedBudget ? Number(l.raw_payload.estimatedBudget).toLocaleString('de-DE') + ' EUR' : '-'],
  ['Why', s.reason],
];

return { json: {
  subject: 'Heißer Lead / Hot lead (' + s.score + '): ' + (l.company || name),
  html: [
    '<h3>Heißer Lead / Hot lead</h3>',
    '<table cellpadding="4">',
    ...rows.map(([k, v]) => '<tr><td><b>' + k + '</b></td><td>' + (k === 'Contact' ? v : esc(v)) + '</td></tr>'),
    '</table>',
    '<p><b>Message:</b><br>' + esc(l.message || '-').replace(/\n/g, '<br>') + '</p>',
    crmLink ? '<p><a href="' + esc(crmLink) + '">Open opportunity in Twenty</a></p>' : '',
  ].join('\n'),
} };
